const test = require('node:test');
const assert = require('node:assert/strict');
const app = require('../lib/branch-digest.cjs');
const { createHash } = require('node:crypto');
test('independent branches retain their common prefix', () => {
  for(const [prefix,tails] of [['invoice:', ['north','south','','north']],['星', ['河','😀','']],['', ['','abc']],['unused',[]]]) {
    const before=[...tails];
    const expected=tails.map(tail=>createHash('sha256').update(prefix+tail,'utf8').digest('hex'));
    assert.deepEqual(app.branchDigests(prefix,tails),expected);
    assert.deepEqual(tails,before);
  }
});
test('known SHA-256 vector and output representation', () => {
  assert.deepEqual(app.branchDigests('a',['bc']),['ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad']);
});
test('concatenate JS strings before UTF-8 encoding across a surrogate boundary', () => {
  assert.deepEqual(app.branchDigests('\ud83d', ['\ude00', '', 'x']),
    ['\ude00', '', 'x'].map(tail => createHash('sha256').update('\ud83d' + tail, 'utf8').digest('hex')));
});

